enum{N55_NPC_DISABLED=1,N55_NPC_HIDDEN=2,N55_NPC_CORE=4,N55_NPC_VIEW=8,N55_NPC_DIRECTION=16,N55_NPC_POSITION64=128};
typedef struct{unsigned char flags[NPC_RECORD_COUNT55],direction[NPC_RECORD_COUNT55];int view[NPC_RECORD_COUNT55];char*display[NPC_RECORD_COUNT55];unsigned x64[NPC_RECORD_COUNT55],y64[NPC_RECORD_COUNT55],seasonMask64;}NpcScene55;
static int npc_scene_available64(const NpcScene55*s,unsigned index){if(index>=NPC_RECORD_COUNT55||mercenary_npc_disabled191(npcRecords55[index].name))return 0;unsigned season=npc_season_required64(index);return !season||(s->seasonMask64&season)!=0;}
#define NPC_ENTITY_BASE55 1000000u
static unsigned npc_scene_index55(uint32_t entity){return entity>NPC_ENTITY_BASE55&&entity-NPC_ENTITY_BASE55<=NPC_RECORD_COUNT55?entity-NPC_ENTITY_BASE55-1:UINT32_MAX;}
static unsigned npc_scene_view55(const NpcScene55*s,unsigned index){return(unsigned)((s->flags[index]&N55_NPC_VIEW)?s->view[index]:npcRecords55[index].view);}
static unsigned npc_scene_direction55(const NpcScene55*s,unsigned index){return(s->flags[index]&N55_NPC_DIRECTION)?s->direction[index]:npcRecords55[index].direction;}
static const char*npc_scene_name55(const NpcScene55*s,unsigned index){return s->display[index]?s->display[index]:npcRecords55[index].name;}
static int npc_scene_model55(const NpcScene55*s,unsigned index){unsigned view=npc_scene_view55(s,index),lo=0,hi=NPC_MODEL_COUNT55;while(lo<hi){unsigned mid=lo+(hi-lo)/2;if(npcModels55[mid].view<view)lo=mid+1;else hi=mid;}return lo<NPC_MODEL_COUNT55&&npcModels55[lo].view==view?(int)lo:-1;}
static float npc_scene_x64(const NpcScene55*s,unsigned i){return(s->flags[i]&N55_NPC_POSITION64)?s->x64[i]:npcRecords55[i].x;}
static float npc_scene_y64(const NpcScene55*s,unsigned i){return(s->flags[i]&N55_NPC_POSITION64)?s->y64[i]:npcRecords55[i].y;}
static int npc_scene_near55(const NpcScene55*s,const Combat*g){if(g->hp<=0||g->hideLeft>0||g->mapId>=sizeof(npcMapSpans55)/sizeof(*npcMapSpans55))return-1;int found=-1;float best=28.001f*28.001f;unsigned start=npcMapSpans55[g->mapId].start,count=npcMapSpans55[g->mapId].count;for(unsigned j=0;j<count;j++){unsigned i=npcMapRecords55[start+j];const NpcRecord55*n=npcRecords55+i;if(!npc_scene_available64(s,i)||(n->flags&6)||(s->flags[i]&(N55_NPC_DISABLED|N55_NPC_HIDDEN|N55_NPC_CORE))||n->kind||!n->program||(npc_scene_model55(s,i)<0&&npc_scene_view55(s,i)!=111))continue;if(!rooms_near181(&interiorRooms181,g->x,g->y,npc_scene_x64(s,i),npc_scene_y64(s,i)))continue;float x=g->x-npc_scene_x64(s,i),y=g->y-npc_scene_y64(s,i),d=x*x+y*y;if(d<best){best=d;found=(int)i;}}return found;}
static uint64_t npc_scene_owner55(void*context,const char*name){(void)context;int i=npc_record_name55(name);return i<0||!npcRecords55[i].program?0:npcProgramFiles55[npcRecords55[i].program-1].owner;}
static int npc_scene_arg55(NpcMachine55*m,NpcValue55 arg,int*index){NpcValue55 value;if(!npc_vm_value55(m,arg,&value)||value.kind!=N55_STRING_KIND)return 0;*index=npc_record_name55(value.text);return 1;}
static int npc_scene_command55(NpcScene55*s,unsigned current,NpcMachine55*m,const char*name,const NpcValue55*args,uint32_t count,NpcValue55*out){*out=npc_vm_number55(0);
 if(!strcmp(name,"movenpc")){int i;int64_t x,y;if(count!=3||!npc_scene_arg55(m,args[0],&i)||!npc_vm_integer55(m,args[1],&x)||!npc_vm_integer55(m,args[2],&y))return N55_ERROR;if(i<0)return N55_READY;unsigned map=npcRecords55[i].map;if(map>=MYRO_MAP_COUNT43||x<0||y<0||x>=(int64_t)mapWidth43[map]/8||y>=(int64_t)mapHeight43[map]/8)return N55_ERROR;s->x64[i]=(unsigned)x*8+4;s->y64[i]=(unsigned)y*8+4;s->flags[i]|=N55_NPC_POSITION64;return N55_READY;}
 if(!strcmp(name,"enablenpc")||!strcmp(name,"disablenpc")||!strcmp(name,"hideonnpc")||!strcmp(name,"hideoffnpc")){int i;if(count!=1||!npc_scene_arg55(m,args[0],&i))return N55_ERROR;if(i<0)return N55_READY;if(!strcmp(name,"enablenpc"))s->flags[i]&=(unsigned char)~N55_NPC_DISABLED;else if(!strcmp(name,"disablenpc"))s->flags[i]|=N55_NPC_DISABLED;else if(!strcmp(name,"hideonnpc"))s->flags[i]|=N55_NPC_HIDDEN;else s->flags[i]&=(unsigned char)~N55_NPC_HIDDEN;return N55_READY;}
 if(!strcmp(name,"getnpcid")){int i=(int)current;if(count>1)return N55_ERROR;if(count&&!npc_scene_arg55(m,args[0],&i)){if(m->status==N55_ERROR)return N55_ERROR;i=-1;}*out=npc_vm_number55(i>=0&&(unsigned)i<NPC_RECORD_COUNT55?NPC_ENTITY_BASE55+npcRecords55[i].id:0);return N55_READY;}
 if(!strcmp(name,"strnpcinfo")){int64_t type;if(count<1||count>3||!npc_vm_integer55(m,args[0],&type)||type<0||type>4)return N55_ERROR;unsigned i=current;if(count==3){int64_t id;if(!npc_vm_integer55(m,args[2],&id)||id<0||id>UINT32_MAX)return N55_ERROR;i=npc_scene_index55((uint32_t)id);}if(i>=NPC_RECORD_COUNT55){*out=count>=2?args[1]:npc_vm_string55("");return N55_READY;}const char*display=npc_scene_name55(s,i),*hash=strchr(display,'#');if(type==0)*out=npc_vm_string55(display);else if(type==2)*out=npc_vm_string55(hash?hash+1:"");else if(type==3)*out=npc_vm_string55(npcRecords55[i].unique);else if(type==4)*out=npc_vm_string55(npcRecords55[i].map<65535?mapNames[npcRecords55[i].map]:"");else{if(!hash)*out=npc_vm_string55(display);else{size_t n=(size_t)(hash-display);if(n+1>NPC_VM_TEXT55-m->textUsed)return N55_ERROR;char*p=m->text+m->textUsed;memcpy(p,display,n);p[n]=0;m->textUsed+=(uint32_t)n+1;*out=npc_vm_string55(p);}}return N55_READY;}
 if(!strcmp(name,"setnpcdir")){int i;int64_t dir;if(count!=2||!npc_scene_arg55(m,args[0],&i)||!npc_vm_integer55(m,args[1],&dir)||dir<0||dir>7)return N55_ERROR;if(i>=0){s->flags[i]|=N55_NPC_DIRECTION;s->direction[i]=(unsigned char)dir;}return N55_READY;}
 if(!strcmp(name,"setnpcdisplay")){int i;if(count<2||count>4||!npc_scene_arg55(m,args[0],&i))return N55_ERROR;if(i<0||npcRecords55[i].map==65535){*out=npc_vm_number55(1);return N55_READY;}NpcValue55 value;if(!npc_vm_value55(m,args[1],&value))return N55_ERROR;int64_t view=-1,size=-1;if(value.kind==N55_NUMBER_KIND)view=value.number;if(count>=3&&!npc_vm_integer55(m,args[2],&view))return N55_ERROR;if(count==4&&(!npc_vm_integer55(m,args[3],&size)||size!=-1))return N55_ERROR;if(view< -1||view>32767)return N55_ERROR;char*copy=NULL;if(value.kind==N55_STRING_KIND){size_t n=strlen(value.text);if(n>63)n=63;copy=malloc(n+1);if(!copy)return N55_ERROR;memcpy(copy,value.text,n);copy[n]=0;}if(copy){free(s->display[i]);s->display[i]=copy;}if(view!=-1){s->flags[i]|=N55_NPC_VIEW;s->view[i]=(int)view;}return N55_READY;}
 return-1;
}
static void npc_scene_clear55(NpcScene55*s){for(unsigned i=0;i<NPC_RECORD_COUNT55;i++)free(s->display[i]);memset(s,0,sizeof(*s));}
